import type { ActionResult } from "@aicore-fivem/shared";
import type { ClothesState } from "./clothes";
/** Wire and NUI contract of ai-inventory: shapes sent between server, client and the screen. No natives. */

export type Metadata = Record<string, unknown>;

export interface Stack {
  slot: number;
  name: string;
  count: number;
  metadata: Metadata;
  rotated: boolean;
}

export type InventoryKind =
  "player" | "drop" | "stash" | "trunk" | "glovebox" | "temp" | "other";

export interface InventoryView {
  id: string;
  kind: InventoryKind;
  label: string;
  columns: number;
  rows: number;
  maxWeight: number;
  stacks: Stack[];
}

/** What sits next to the player inventory when it is not another inventory. */
export type Panel =
  { kind: "shop"; id: string } | { kind: "bench"; id: string };

export type OpenTarget =
  | { kind: "self" }
  | { kind: "drop"; id: string }
  | { kind: "stash"; id: string }
  | { kind: "trunk"; netId: number }
  | { kind: "glovebox" }
  | { kind: "shop"; id: string }
  | { kind: "bench"; id: string };

export type OpenResult = ActionResult<{
  other: InventoryView | null;
  panel: Panel | null;
}>;

export interface MoveInput {
  from: string;
  fromSlot: number;
  to: string;
  toSlot: number;
  count: number;
  rotated: boolean;
}

export interface DropPoint {
  id: string;
  x: number;
  y: number;
  z: number;
}

export interface EquippedWeapon {
  slot: number;
  name: string;
  ammo: number;
  components: string[];
}

/** Item fields the screen needs (from the panel's item list). */
export interface ItemView {
  name: string;
  label: string;
  description: string;
  weight: number;
  w: number;
  h: number;
  stack: number;
  type: string;
  usable: boolean;
  image: string;
  /** Attachment items: the GTA component names they can be. */
  hashes: string[];
  /** The rarity's colour (`#rrggbb`), "" = none: the tile takes it. */
  rarity: string;
}

export interface ShopView {
  id: string;
  label: string;
  items: Array<{ name: string; price: number }>;
}

export interface BenchView {
  id: string;
  label: string;
  recipes: Array<{
    result: string;
    count: number;
    time: number;
    ingredients: Array<{ name: string; count: number }>;
  }>;
}

/** Client -> NUI messages. */
export type NuiMessage =
  | {
      action: "setup";
      data: { texts: Record<string, string>; items: ItemView[] };
    }
  | { action: "items"; data: ItemView[] }
  | { action: "player"; data: InventoryView }
  | {
      action: "open";
      data: {
        other: InventoryView | null;
        shop: ShopView | null;
        bench: BenchView | null;
        /** The open key as bound now: the screen closes on it too. */
        key: string;
      };
    }
  | {
      action: "delta";
      data: { id: string; put: Stack[]; remove: number[]; maxWeight: number };
    }
  | { action: "profile"; data: { name: string; clothes: ClothesState } }
  | { action: "close"; data: null }
  /** The quick slots bar at the bottom while the inventory is closed (Tab). */
  | { action: "hotbar"; data: boolean }
  | { action: "otherClosed"; data: null }
  /** The drop the player just made replaces the ground panel (snapshot; deltas follow). */
  | { action: "ground"; data: InventoryView }
  /** The panel changed an inventory's columns, rows or weight limit. */
  | {
      action: "layout";
      data: { id: string; columns: number; rows: number; maxWeight: number };
    };

/** NUI -> client callbacks (fetchNui names). */
export const NUI = {
  close: "close",
  move: "move",
  use: "use",
  give: "give",
  drop: "drop",
  buy: "buy",
  craft: "craft",
  detach: "detach",
  clothes: "clothes",
  worldPed: "worldPed",
} as const;
